/**
 * Normalizes LiteLLM's `model_prices_and_context_window.json` into the bundled price table
 * (`src/data/prices.json`, regenerated by `scripts/prices-update.ts`).
 *
 * LiteLLM prices are USD per token; the table is USD per million tokens, rounded to 6 decimal
 * places so float noise (`2.9999999999999996`) never reaches the committed JSON. Only the
 * first-party API providers the router talks to are kept, and only chat / embedding models.
 * Batch, flex, priority and regional rates are not mapped (the router bills standard rates).
 *
 * The input is untrusted data: every field is type-checked and a bad field is dropped rather
 * than failing the whole table. Output keys are sorted and each entry's fields follow the
 * `PriceEntry` declaration order, so a regenerated table diffs cleanly.
 */
import type { PriceEntry, PriceTable } from "./prices.ts";

/** LiteLLM `litellm_provider` → price-table provider. Everything else is skipped. */
const PROVIDERS: Readonly<Record<string, string>> = {
  anthropic: "anthropic",
  openai: "openai",
  gemini: "google",
  openrouter: "openrouter",
  mistral: "mistral",
  xai: "xai",
  deepseek: "deepseek",
};

/** Long-context tier fields, e.g. `input_cost_per_token_above_200k_tokens`. */
const TIER_KEY =
  /^(input_cost_per_token|output_cost_per_token|cache_read_input_token_cost)_above_(\d+)([km]?)_tokens$/;

const TIER_FIELD = {
  input_cost_per_token: "input",
  output_cost_per_token: "output",
  cache_read_input_token_cost: "cacheRead",
} as const;

type Tier = NonNullable<PriceEntry["aboveTokens"]>;

export function normalizeLiteLLM(
  raw: unknown,
  meta: { source: string; generatedAt: string },
): PriceTable {
  if (!isRecord(raw)) throw new TypeError("LiteLLM price data must be a JSON object");

  const picked = new Map<string, { entry: PriceEntry; prefixed: boolean }>();
  for (const [key, value] of Object.entries(raw)) {
    if (key === "sample_spec" || !isRecord(value)) continue;
    const litellmProvider = own(value, "litellm_provider");
    if (typeof litellmProvider !== "string" || !Object.hasOwn(PROVIDERS, litellmProvider)) {
      continue;
    }
    const provider = PROVIDERS[litellmProvider];
    if (provider === undefined) continue;

    const prefix = `${litellmProvider}/`;
    const prefixed = key.startsWith(prefix);
    const modelId = prefixed ? key.slice(prefix.length) : key;
    if (modelId === "") continue;

    const entry = toEntry(value);
    if (entry === undefined) continue;

    const ref = `${provider}/${modelId}`;
    const existing = picked.get(ref);
    // Collisions (`gemini-pro-latest` vs `gemini/gemini-pro-latest`): the unprefixed key wins,
    // otherwise the first one seen.
    if (existing === undefined || (existing.prefixed && !prefixed)) {
      picked.set(ref, { entry, prefixed });
    }
  }

  const models: Record<string, PriceEntry> = {};
  for (const ref of [...picked.keys()].sort()) {
    const hit = picked.get(ref);
    if (hit !== undefined) models[ref] = hit.entry;
  }
  return {
    source: meta.source,
    generatedAt: meta.generatedAt,
    unit: "usd_per_million_tokens",
    models,
  };
}

function toEntry(v: Record<string, unknown>): PriceEntry | undefined {
  const input = perMillion(own(v, "input_cost_per_token"));
  if (input === undefined) return undefined;
  let output = perMillion(own(v, "output_cost_per_token"));

  const rawMode = own(v, "mode");
  let mode: PriceEntry["mode"];
  if (rawMode === "chat" || rawMode === "responses") {
    mode = "chat";
  } else if (rawMode === "embedding") {
    mode = "embedding";
    output ??= 0;
  } else if (rawMode === undefined && output !== undefined) {
    mode = "chat";
  } else {
    return undefined;
  }
  // A chat model without an output rate would be billed as free output: skip it.
  if (output === undefined) return undefined;

  // Built field by field in `PriceEntry` declaration order.
  const entry: PriceEntry = { mode, input, output };
  const cacheRead = perMillion(own(v, "cache_read_input_token_cost"));
  if (cacheRead !== undefined) entry.cacheRead = cacheRead;
  const cacheWrite = perMillion(own(v, "cache_creation_input_token_cost"));
  if (cacheWrite !== undefined) entry.cacheWrite = cacheWrite;
  const cacheWrite1h = perMillion(own(v, "cache_creation_input_token_cost_above_1hr"));
  if (cacheWrite1h !== undefined) entry.cacheWrite1h = cacheWrite1h;
  const tier = longContextTier(v);
  if (tier !== undefined) entry.aboveTokens = tier;
  const contextWindow = tokenCount(own(v, "max_input_tokens")) ?? tokenCount(own(v, "max_tokens"));
  if (contextWindow !== undefined) entry.contextWindow = contextWindow;
  const maxOutput = tokenCount(own(v, "max_output_tokens"));
  if (maxOutput !== undefined) entry.maxOutput = maxOutput;
  const toolCalling = flag(own(v, "supports_function_calling"));
  if (toolCalling !== undefined) entry.toolCalling = toolCalling;
  const vision = flag(own(v, "supports_vision"));
  if (vision !== undefined) entry.vision = vision;
  const reasoning = flag(own(v, "supports_reasoning"));
  if (reasoning !== undefined) entry.reasoning = reasoning;
  const promptCaching = flag(own(v, "supports_prompt_caching"));
  if (promptCaching !== undefined) entry.promptCaching = promptCaching;
  return entry;
}

/** The lowest long-context threshold with at least one valid rate. */
function longContextTier(v: Record<string, unknown>): Tier | undefined {
  const byThreshold = new Map<number, Partial<Record<"input" | "output" | "cacheRead", number>>>();
  for (const [key, value] of Object.entries(v)) {
    const m = TIER_KEY.exec(key);
    if (m === null) continue;
    const [, base, digits, unit] = m;
    if (base === undefined || digits === undefined) continue;
    const field = TIER_FIELD[base as keyof typeof TIER_FIELD];
    const threshold = Number(digits) * (unit === "m" ? 1_000_000 : unit === "k" ? 1_000 : 1);
    const rate = perMillion(value);
    if (field === undefined || rate === undefined || !Number.isSafeInteger(threshold)) continue;
    if (threshold <= 0) continue;
    const rates = byThreshold.get(threshold) ?? {};
    rates[field] = rate;
    byThreshold.set(threshold, rates);
  }
  if (byThreshold.size === 0) return undefined;
  const threshold = Math.min(...byThreshold.keys());
  const rates = byThreshold.get(threshold) ?? {};
  const tier: Tier = { threshold };
  if (rates.input !== undefined) tier.input = rates.input;
  if (rates.output !== undefined) tier.output = rates.output;
  if (rates.cacheRead !== undefined) tier.cacheRead = rates.cacheRead;
  return tier;
}

/** USD per token → USD per million tokens, 6 decimal places. */
function perMillion(value: unknown): number | undefined {
  if (typeof value !== "number" || !Number.isFinite(value) || value < 0) return undefined;
  const rate = Math.round(value * 1e12) / 1e6;
  return Number.isFinite(rate) ? rate : undefined;
}

function tokenCount(value: unknown): number | undefined {
  return typeof value === "number" && Number.isSafeInteger(value) && value > 0 ? value : undefined;
}

function flag(value: unknown): boolean | undefined {
  return typeof value === "boolean" ? value : undefined;
}

function own(obj: Record<string, unknown>, key: string): unknown {
  return Object.hasOwn(obj, key) ? obj[key] : undefined;
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}
